# -*- coding: utf-8 -*-

import json
import os.path
import shutil
from datetime import date
try:
    from mail import notification
except ImportError:
    def notification(*args, **kwargs):
        pass

import pytest

today = str(date.today())
BASE_DIR = os.path.dirname(__file__)


def pytest_addoption(parser):
    group = parser.getgroup('count')
    group.addoption(
        '--count',
        action='store_true',
        dest='counter',
        default=False,
        help='Show number of erros '
    )


new_failures = {'erros': []}


filename = os.path.join(BASE_DIR, 'failures.json')
filename_old = os.path.join(BASE_DIR, 'old_failures.json')

@pytest.hookimpl
def pytest_sessionstart(session):
    global filename
    global filename_old

    if os.path.exists(filename):
        try:
            shutil.copy(filename, filename_old)
        except Exception:
            pass


@pytest.hookimpl(tryfirst=True, hookwrapper=True)
def pytest_runtest_makereport(item, call):
    global new_failures

    outcome = yield
    rep = outcome.get_result()
    if rep.when != 'call' or getattr(rep, 'fspath', '') == 'tests/test_count.py':
        return

    if rep.failed:
        if 'tmpdir' in getattr(item, 'fixturenames', []):
            extra = ' (%s)' % item.funcargs.get('tmpdir', '')
        else:
            extra = ''

        new_failures['erros'].append({'id': getattr(rep, 'nodeid', ''), 'extra': extra})

    try:
        with open(filename, 'w') as f:
            json.dump(new_failures, f)
    except Exception:
        pass


@pytest.hookimpl
def pytest_sessionfinish(session):
    global filename
    global filename_old

    try:
        if isinstance(filename, str) and os.path.exists(filename):
            with open(filename, 'r') as f:
                new_data = json.load(f)
        else:
            new_data = {'erros': []}

        if isinstance(filename_old, str) and os.path.exists(filename_old):
            with open(filename_old, 'r') as f:
                old_data = json.load(f)
        else:
            old_data = {'erros': []}

        if len(new_data.get('erros', [])) > len(old_data.get('erros', [])):
            notification(len(new_data.get('erros', [])))
    except Exception:
        pass
